<?php $pageTitle='Dashboard';require __DIR__.'/header.php';?><div class="head"><div><b class="eyebrow"><?=strtoupper($user['role'])?> DASHBOARD</b><h1>Hello, <?=htmlspecialchars($user['name'])?> 👋</h1></div></div><?php if($user['role']==='admin'):?><div class="stats"><?php foreach($stats as $k=>$v):?><div class="stat"><small><?=$k?></small><strong><?=intval($v)?></strong></div><?php endforeach;?></div><a class="btn primary" href="index.php?action=admin">Open Admin Panel</a><?php elseif($user['role']==='patient'):?><div class="stats"><div class="stat"><small>Total</small><strong><?=intval($stats['total']??0)?></strong></div><div class="stat"><small>Pending</small><strong><?=intval($stats['pending']??0)?></strong></div><div class="stat"><small>Completed</small><strong><?=intval($stats['completed']??0)?></strong></div></div><a class="btn primary" href="index.php?action=doctors">Find a Doctor</a><?php elseif($user['role']==='doctor'):?><div class="stats"><div class="stat"><small>Total</small><strong><?=intval($stats['total']??0)?></strong></div><div class="stat"><small>Today</small><strong><?=intval($stats['today']??0)?></strong></div><div class="stat"><small>Completed</small><strong><?=intval($stats['completed']??0)?></strong></div></div><a class="btn primary" href="index.php?action=doctor_schedule">Today's Schedule</a><?php else:?><div class="card"><h2>Reception Desk</h2><p>Check in patients, mark no-shows and book walk-ins.</p><a class="btn primary" href="index.php?action=reception">Open Desk</a></div><?php endif;?><?php if($recent):?><section class="card"><h2>Recent Queue</h2><div class="table"><table><tr><th>Date</th><th>Patient</th><th>Doctor</th><th>Status</th></tr><?php foreach($recent as $a):?><tr><td><?=$a['appointment_date']?></td><td><?=htmlspecialchars($a['patient_name']??'-')?></td><td><?=htmlspecialchars($a['doctor_name'])?></td><td><span class="badge <?=$a['status']?>"><?=$a['status']?></span></td></tr><?php endforeach;?></table></div></section><?php endif;?><?php require __DIR__.'/footer.php';?>